        if r['source_type'] not in ('owner_review','owner_forum','owner_survey','press_review'): errs.append((n,'st'))
        per[(r['model'],r['source_type'],r['evidence_tier'])]+=1; refs[(r['model'],r['source_type'])].add(r['review_ref'])
    if r['kind']=='equipment':
        if r['feature'][:3] not in feats: errs.append((n,'feat',r['feature']))
        if r['availability'] not in ('standard','optional','not_available','unknown'): errs.append((n,'avail'))
        if r['theme'] not in themes: errs.append((n,'theme'))
        per[(r['model'],'equipment',r['feature'][:3])]+=0
        per[(r['model'],'equipment')]+=1
print('errors:',errs or 'none'); print(dict(kinds))
for k,v in sorted(per.items(),key=str):
    if v: print(k,v)
for k,v in sorted(refs.items()): print('refs',k,len(v))
